
/* Nouveau « Récap du Camp » : 16 écrans illustrés (remplace l'ancien récap animé) */
(function(){
 var IMG=[{"c":"#013a83","u":"data:image/webp;base64,"},{"c":"#003885","u":"data:image/webp;base64,"},{"c":"#00357e","u":"data:image/webp;base64,"},{"c":"#003683","u":"data:image/webp;base64,"},{"c":"#003984","u":"data:image/webp;base64,"},{"c":"#032f78","u":"data:image/webp;base64,"},{"c":"#043c85","u":"data:image/webp;base64,"},{"c":"#0a3b66","u":"data:image/webp;base64,"},{"c":"#0b3d62","u":"data:image/webp;base64,"},{"c":"#023985","u":"data:image/webp;base64,"},{"c":"#00337b","u":"data:image/webp;base64,"},{"c":"#023580","u":"data:image/webp;base64,"},{"c":"#0c4d96","u":"data:image/webp;base64,"},{"c":"#012e6f","u":"data:image/webp;base64,"},{"c":"#062e76","u":"data:image/webp;base64,"},{"c":"#003377","u":"data:image/webp;base64,"}];
 var N=IMG.length,DUR=5000,idx=0,el=0,paused=false,last=0,raf=0,rn=null,bars=[],slides=[],opening=false,t0=0,lk=false;
 function bg(k){var s=slides[k];if(!s)return;if(!s.style.backgroundImage)s.style.backgroundImage='url('+IMG[k].u+')'}
 function unbg(k){var s=slides[k];if(s&&s.style.backgroundImage)s.style.backgroundImage=''}
 function go(i){
  idx=Math.max(0,Math.min(N-1,i));el=0;
  for(var k=0;k<N;k++){bars[k].style.transform=k<idx?'scaleX(1)':'scaleX(0)';slides[k].classList.toggle('on',k===idx);
   if(Math.abs(k-idx)<=1)bg(k);else unbg(k)}
  rn.querySelector('.rn-n').textContent=(idx+1)+'/'+N;
  rn.querySelector('.rn-cw').classList.toggle('on',idx===N-1)}
 function tick(ts){if(!rn)return;if(!last)last=ts;if(!paused)el+=ts-last;last=ts;
  bars[idx].style.transform='scaleX('+Math.min(1,el/DUR)+')';
  if(el>=DUR){if(idx<N-1)go(idx+1);else{bars[idx].style.transform='scaleX(1)';el=DUR-1;paused=true}}
  raf=requestAnimationFrame(tick)}
 function finish(){if(!rn)return;var e=rn;rn=null;cancelAnimationFrame(raf);e.classList.remove('on');document.body.style.overflow='';setTimeout(function(){e.remove()},320);try{window.dispatchEvent(new Event('campRecapEnd'))}catch(x){}}
 function open(locked){if(rn)return;lk=!!locked;
  if(rn)return;
  var e=document.createElement('div');e.className='rn'+(lk?' lk':'');e.setAttribute('role','dialog');e.setAttribute('aria-modal','true');e.setAttribute('aria-label','Récap du Camp');
  var h='<div class="rn-stage">';
  for(var k=0;k<N;k++)h+='<div class="rn-sl" style="--tc:'+IMG[k].c+'"></div>';
  h+='<div class="rn-top"><div class="rn-bars">'+new Array(N+1).join('<i><b></b></i>')+'</div><div class="rn-hd"><b>Récap du Camp</b><span class="rn-n">1/'+N+'</span><button type="button" class="rn-x" aria-label="Fermer">×</button></div></div>';
  h+='<div class="rn-cw"><button type="button" class="rn-cta">Je me pré-inscris</button></div></div>';
  e.innerHTML=h;document.body.appendChild(e);rn=e;document.body.style.overflow='hidden';
  bars=[].slice.call(e.querySelectorAll('.rn-bars b'));slides=[].slice.call(e.querySelectorAll('.rn-sl'));
  go(0);last=0;paused=false;raf=requestAnimationFrame(tick);
  requestAnimationFrame(function(){requestAnimationFrame(function(){e.classList.add('on')})});
  e.addEventListener('pointerdown',function(ev){if(lk||ev.target.closest('button'))return;paused=true;t0=Date.now()});
  function up(ev){if(lk||!paused)return;if(idx===N-1&&el>=DUR-1&&ev.type==='pointerup'&&Date.now()-t0<250){var x0=ev.clientX>innerWidth/2;paused=false;if(x0){finish();return}go(idx-1);return}
   paused=false;if(ev.type==='pointerup'&&Date.now()-t0<250){var st=e.querySelector('.rn-stage').getBoundingClientRect();(ev.clientX>st.left+st.width/2)?(idx<N-1?go(idx+1):finish()):go(idx-1)}}
  e.addEventListener('pointerup',up);e.addEventListener('pointercancel',up);
  e.querySelector('.rn-x').onclick=finish;
  var cta=e.querySelector('.rn-cta');if(lk)cta.textContent='Continuer';
  cta.onclick=function(){if(lk){lk=false;try{localStorage.setItem('camp_recap_done','1');localStorage.removeItem('camp_recap_lock')}catch(x){}finish();return}finish();window.openRegistration&&window.openRegistration()}}
 document.addEventListener('keydown',function(ev){if(!rn||lk)return;if(ev.key==='Escape')finish();else if(ev.key==='ArrowRight')idx<N-1?go(idx+1):finish();else if(ev.key==='ArrowLeft')go(idx-1)});
 document.addEventListener('visibilitychange',function(){if(rn)paused=document.hidden});
 document.addEventListener('click',function(ev){
  var t=ev.target;if(!t||!t.closest||!t.closest('#v58Scene'))return;
  ev.stopImmediatePropagation();ev.stopPropagation();
  if(rn||opening)return;opening=true;
  if(navigator.vibrate)try{navigator.vibrate(20)}catch(x){}
  try{localStorage.setItem('camp_recap_seen','1')}catch(x){}
  var hint=document.getElementById('v209Hint');if(hint)hint.style.opacity='0';
  setTimeout(function(){opening=false;open(lockPending())},450)},true);
 /* 1re inscription : récap verrouillé (ni fermeture, ni passage manuel) jusqu'au bouton « Continuer » */
 function lockPending(){try{return localStorage.getItem('camp_recap_lock')==='1'&&!!localStorage.getItem('camp_registration_2026')&&localStorage.getItem('camp_recap_done')!=='1'}catch(x){return false}}
 window.campFirstRecap=function(){try{if(localStorage.getItem('camp_recap_done')==='1')return;localStorage.setItem('camp_recap_lock','1')}catch(x){return}
  setTimeout(function(){if(!rn&&lockPending())open(true)},1400)};
 setTimeout(function(){if(!rn&&lockPending())open(true)},1200);
 window.campIntro=function(){if(!rn)open(false)};
})();

